# invoice_summary.py\n# [LATER-STEP] Summarize extracted invoice fields\n\nfrom document_models import InvoiceExtractionResponse, NormalizedExpense\n\ndef summarize_invoice(response: InvoiceExtractionResponse) -> str:\n    \"\"\"Creates a concise human‑readable summary from an invoice extraction result.\n\n    Args:\n        response (InvoiceExtractionResponse): The raw extraction payload.\n\n    Returns:\n        str: A short summary string.\n    \"\"\"\n    # Basic formatting – could be expanded with additional business logic\n    lines = [\n        f\"Vendor: {response.vendor}\",\n        f\"Date: {response.date}\",\n        f\"Total: ${response.total:.2f}\",\n        \"Line Items:\",\n    ]\n    for i, item in enumerate(response.line_items, 1):\n        lines.append(f\"  {i}. {item}\")\n    return \"\\n\".join(lines)\n\ndef summarize_normalized(expense: NormalizedExpense) -> str:\n    \"\"\"Creates a summary from a normalized expense record (used after LLM inference).\n\n    Args:\n        expense (NormalizedExpense): The normalized expense object.\n\n    Returns:\n        str: Summary string.\n    \"\"\"\n    return (f\"Expense Summary - Vendor: {expense.vendor}\\nDate: {expense.date}\\nTotal: ${expense.total:.2f}\\nItems: {len(expense.items)} items\")\n
